  if (!brief.days.has(date) && brief.sha) readDay(date).then(renderBrief).catch(() => renderBrief());
}

function renderBrief() {
  const section = $('lead-digest-section');
  if (!brief.config?.digestsRepo) { section.hidden = true; return; }
