  const entry = brief.days.get(date) ?? null;
  $('fleet-digest').replaceChildren(entry
    ? digestCard(entry, brief.config.digestsRepo, brief.config.digestsPath)
    : el('div', { className: 'chart-card lead-card digest' }, [
